using System;using System.Linq;using System.Collections.Generic;using System.Globalization;
namespace Purrington.Domain {
public sealed partial class HotelModel {
 HotelModel(ParityContent content,HotelState candidate){Content=content;State=candidate;}
 static bool ValidateContent(HotelState s){try{var content=ParityContent.Current;if(content==null)return false;var candidate=Copy(s);var model=new HotelModel(content,candidate);var instanceIds=new List<string>();for(int i=0;i<4;i++){var h=candidate.hotels[i];if(!model.ValidTown(h.town,TownContent.Current,i))return false;if(h.visits<0||h.happy<0||h.cleaned<0||h.purchases<0||h.dirtCursor<0||!Finite(h.dirtClock)||h.dirtClock<0||h.plots.Distinct().Count()!=h.plots.Count)return false;var plots=content.Maps[i]["plots"].Select(p=>(string)p["id"]).ToArray();if(h.plots.Any(p=>!plots.Contains(p)))return false;foreach(var path in h.paths){var parts=path.Key.Split(',');if(parts.Length!=2||!int.TryParse(parts[0],NumberStyles.Integer,CultureInfo.InvariantCulture,out int x)||!int.TryParse(parts[1],NumberStyles.Integer,CultureInfo.InvariantCulture,out int z)||path.Key!=x+","+z||Math.Abs(x)>256||Math.Abs(z)>256)return false;var p=path.Value;if(p==null||!new[]{"earth","gravel","brick"}.Contains(p.style)||!Finite(p.paid)||p.paid<0||p.paid>(p.style=="earth"?2:p.style=="gravel"?4:6)||!model.Owns(new LotRect(x,z,1,1),i))return false;}if(h.dirty.Keys.Any(string.IsNullOrEmpty))return false;if(!model.ValidateLayout(i).success||!model.ValidateShell(i).success)return false;for(int n=0;n<h.objects.Count;n++)if(h.objects[n].room!=s.hotels[i].objects[n].room)return false;instanceIds.AddRange(h.rooms.Select(r=>r.id));instanceIds.AddRange(h.objects.Select(o=>o.id));}instanceIds.AddRange(s.storage.Select(o=>o.id));foreach(string id in instanceIds)foreach(string prefix in new[]{"room","space","object"})if(id.StartsWith(prefix,StringComparison.Ordinal)){string suffix=id.Substring(prefix.Length);if(int.TryParse(suffix,out int n)&&n.ToString(CultureInfo.InvariantCulture)==suffix&&n>=s.nextId)return false;}if(s.wardrobe.Distinct().Count()!=s.wardrobe.Count)return false;if(Wardrobe.All.Length>0){if(s.wardrobe.Any(w=>Wardrobe.Find(w)==null))return false;foreach(var c in s.cats)foreach(var o in c.outfit){var w=Wardrobe.Find(o.Value);if(!Wardrobe.Slots.Contains(o.Key)||w==null||w.slot!=o.Key)return false;}}if(s.entitlements.Distinct().Count()!=s.entitlements.Count||s.entitlements.Any(e=>!new[]{"purrington.cat_club","purrington.forest_lodge","purrington.snowcap_spa"}.Contains(e)))return false;var preferences=content.Cats.Select(c=>(string)c["preference"]).Distinct().ToArray();foreach(var c in s.cats)if(!preferences.Contains(c.preference)||c.friend<-1||c.friend>=18||c.friend==c.id)return false;return true;}catch(Exception e)when(e is ArgumentException||e is InvalidOperationException||e is NullReferenceException||e is OverflowException){return false;}}
}
}
